		refreshThread: () => app.refreshThread(),
		focusForNavigation,
		threadFocusTarget: (id, options) => app.threadDestinations.threadFocusTarget(id, options),
		clearFor: (destination, landed) => floatingPanel?.clearFor(destination, landed),
